"""Execution result and chart schema validation models."""

import re
from typing import Any, Dict, List, Literal, Optional
from pydantic import BaseModel, Field, field_validator, model_validator


SUPPORTED_CHART_TYPES = {"line", "bar", "scatter", "bar_grouped"}
MAX_CHART_POINTS = 500


class ChartSpec(BaseModel):
    """Schema for /tmp/output/result.json generated by sandbox scripts."""
    chart_type: Literal["line", "bar", "scatter", "bar_grouped"] = Field(
        ..., description="Supported chart visualization type"
    )
    title: str = Field(..., max_length=150, description="Short descriptive title for the chart")
    x_label: Optional[str] = Field(None, max_length=50)
    y_label: Optional[str] = Field(None, max_length=50)
    data: List[Dict[str, Any]] = Field(
        ..., description="Array of data points/rows for the chart"
    )
    series: Optional[List[str]] = Field(
        None, description="Series keys to plot against x-axis"
    )

    @field_validator("data")
    @classmethod
    def validate_data_length(cls, v: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
        if not v:
            raise ValueError("Chart data must not be empty")
        if len(v) > MAX_CHART_POINTS:
            raise ValueError(
                f"Chart data contains {len(v)} points, exceeding maximum limit of {MAX_CHART_POINTS} points"
            )
        return v

    @model_validator(mode="after")
    def validate_chart_keys(self) -> "ChartSpec":
        if not self.data:
            return self
        first_row = self.data[0]
        if not isinstance(first_row, dict):
            raise ValueError("Each item in chart data must be an object/dict")
        if self.series:
            for s in self.series:
                if s not in first_row:
                    raise ValueError(f"Series key '{s}' not found in data points")
        return self


class ExecutionResult(BaseModel):
    """Structured result returned by SandboxExecutor. Never raises exceptions to caller."""
    status: Literal["success", "failed", "timeout", "oom", "daemon_unavailable"] = Field(
        ..., description="Execution status classification"
    )
    stdout: str = Field(default="", description="Captured standard output (capped)")
    stderr: str = Field(default="", description="Captured standard error (capped)")
    exit_code: int = Field(default=0, description="Process exit code")
    duration_seconds: float = Field(default=0.0, description="Execution duration in seconds")
    error_signature: Optional[str] = Field(
        default=None, description="Normalized exception signature for loop/retry detection"
    )
    chart_data: Optional[Dict[str, Any]] = Field(
        default=None, description="Validated chart data if result.json was produced"
    )
    output_files: List[str] = Field(
        default_factory=list, description="Names of files found in /tmp/output"
    )


def compute_error_signature(stderr: str, exception_msg: Optional[str] = None) -> Optional[str]:
    """Extract and normalize exception type and message to detect repeated failures."""
    text = exception_msg or stderr or ""
    if not text.strip():
        return None

    # Search for common Python traceback patterns: e.g. "KeyError: 'foo'" or "ZeroDivisionError: division by zero"
    match = re.search(r"([A-Za-z_][A-Za-z0-9_]*Error|[A-Za-z_][A-Za-z0-9_]*Exception):\s*(.*)", text)
    if match:
        err_type = match.group(1).strip()
        err_msg = match.group(2).strip()
        # Normalize dynamic tokens (hex addresses, numbers, file line numbers)
        normalized_msg = re.sub(r"0x[0-9a-fA-F]+", "<hex>", err_msg)
        normalized_msg = re.sub(r"\d+", "<num>", normalized_msg)
        return f"{err_type}: {normalized_msg[:100]}"

    # Fallback to first line of error or truncated stderr
    first_non_empty = next((line.strip() for line in text.splitlines() if line.strip()), "")
    return re.sub(r"\d+", "<num>", first_non_empty[:120])
